return [{
  json: {
    projeto: "RUPTURA ONE",
    tema: "Como usar inteligência artificial para economizar tempo e aumentar produtividade",
    publico: "brasileiros interessados em IA, produtividade, negócios e renda online",
    plataforma: "TikTok, Instagram Reels e YouTube Shorts",
    objetivo: "gerar um vídeo curto útil, original e com potencial de retenção",
    idioma: "pt-BR",
    tom: "direto, curioso, prático e convincente",
    data_execucao: new Date().toISOString()
  }
}];

const r = $input.first().json;

const text =
  r.output_text ||
  r.outputText ||
  r.text ||
  r?.outputs?.[0]?.text ||
  r?.steps?.find(s => s.type === "model_output")?.content?.find(c => c.type === "text")?.text ||
  "";

if (!text) {
  throw new Error("A Gemini não retornou texto. Verifique a chave da API e a resposta do nó GEMINI — IA REAL.");
}

const cleaned = String(text)
  .replace(/^```json\s*/i, "")
  .replace(/^```\s*/i, "")
  .replace(/\s*```$/i, "")
  .trim();

let content;
try {
  content = JSON.parse(cleaned);
} catch (e) {
  throw new Error("A Gemini retornou texto que não é JSON válido: " + cleaned.slice(0, 800));
}

return [{
  json: {
    ...content,
    gerado_por: "Google Gemini API",
    modelo: r.model || "gemini-3.8-flash",
    gerado_em: new Date().toISOString()
  }
}];

const d = $input.first().json;

const obrigatorios = [
  "titulo",
  "gancho",
  "roteiro",
  "legenda",
  "cta",
  "hashtags",
  "ideia_visual",
  "duracao_segundos"
];

const faltantes = obrigatorios.filter(
  k => d[k] === undefined || d[k] === null || String(d[k]).trim() === ""
);

if (faltantes.length) {
  throw new Error("QA reprovado. Campos ausentes: " + faltantes.join(", "));
}

if (String(d.gancho).length < 15) {
  throw new Error("QA reprovado. Gancho muito curto.");
}

if (String(d.roteiro).length < 180) {
  throw new Error("QA reprovado. Roteiro muito curto.");
}

return [{
  json: {
    ...d,
    qa: {
      aprovado: true,
      campos_verificados: obrigatorios,
      status: "APROVADO"
    },
    status: "CONTEÚDO_REAL_PRONTO"
  }
}];

const d = $input.first().json;

return [{
  json: {
    projeto: "RUPTURA ONE",
    status: d.status,
    gerado_por: d.gerado_por,
    modelo: d.modelo,
    titulo: d.titulo,
    gancho: d.gancho,
    roteiro: d.roteiro,
    legenda: d.legenda,
    cta: d.cta,
    hashtags: d.hashtags,
    ideia_visual: d.ideia_visual,
    duracao_segundos: d.duracao_segundos,
    qa: d.qa,
    gerado_em: d.gerado_em
  }
}];
